            text: "In a computer system employing a segmentation-based memory management scheme, which of the  following task(s) is/are performed by the Memory Management Unit (MMU) hardware during a memory  access cycle?",
            image: "",
            options: [
                'Allocation of a new segment table in the main memory for a newly created process.',
                'Computation of the physical address by adding the segment base address to the logical offset.',
                'Generating a hardware trap if the logical offset exceeds the segment limit specified in  the segment table.',
                'Determining which segments of a process should be swapped out to the disk when  physical memory is full.'
            ],
            answer: ["C", "B"],
            solution: "Allocation of a new segment table is performed by the operating System during  process creation. The MMU only accesses the segment table for address translation; it does  not create or allocate it. So, option (a) is incorrect.<br>During a memory access, the MMU retrieves the segment base address from the segment table  and adds it to the logical offset to compute the physical address. This address  translation is a core hardware function of the MMU. So, option (b) is correct.<br>The MMU checks whether the logical offset is within the segment limit. If the offset  exceeds the limit, it generates a hardware trap (segmentation fault) to ensure memory  protection. So, option (c) is correct.<br>The decision regarding which segments to swap out when memory is full is taken by  the Operating System’s memory manager. The MMU does not perform memory  replacement decisions. So, option (d) is incorrect."
