            type: "MSQ",
            text: "To minimize the routing overhead in Ad-hoc networks, following ideas are incorporated in the prepossessed routing protocols:",
            image: "",
            options: [
                'Perform routing on-demand basis.',
                'Reduce the number of nodes involved in routing by delegating the networking routing function to only some of the neighborhood nodes.',
                'First attempt to perform proactive updates only along the optimal paths determined previously.',
                'None of these'
            ],
